contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive sequence: set storage so that _RState_ == BELOW_ONE and _BASE_RESERVE_ == _BASE_TARGET_,
    // then call correctRState and observe that RState stays BELOW_ONE.
    // We cannot write to c's internals directly; use observable public functions to arrange state.
    // We take inputs that let a caller create initial reserves/targets via buyShares flow.

    // Single external test function as required. It uses parameters to set up balances via token transfers
    // by assuming caller already funded the pool contract c with appropriate tokens. The function will
    // call c.sync() and c.correctRState() and then read R state via getPMMStateForCall().

    // Note: we only interact with c through its public API.
    function runTest(uint256 baseBalanceAfter, uint256 quoteBalanceAfter) external {
        // Preconditions for the test to be meaningful:
        // We require caller to have already transferred tokens into c such that
        // c.getVaultReserve will reflect desired reserves after sync.
        // Call sync to update reserves from token balances.
        c.sync();

        // Query current PMM state to fetch values to use as targets/reserves.
        (uint256 i, uint256 K, uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();

        // We need the situation: R == BELOW_ONE and BASE_RESERVE == BASE_TARGET.
        // If not already satisfied, attempt to create it by calling buyShares with zero base/quote input
        // won't change; so require the precondition here to let verifier choose parameters where it holds.
        require(R == uint256(uint32(1)), "PRE: R must be BELOW_ONE");
        require(B == B0, "PRE: BASE_RESERVE must equal BASE_TARGET");

        // Now call the deciding function that was mutated in M.
        c.correctRState();

        // Read PMM state after the call.
        (uint256 i2, uint256 K2, uint256 B_after, uint256 Q_after, uint256 B0_after, uint256 Q0_after, uint256 R_after) = c.getPMMStateForCall();

        // Property: when originally R was BELOW_ONE and B == B0, calling correctRState MUST NOT set R to ONE.
        // On original P this holds (R_after remains BELOW_ONE). On mutant M it flips to ONE because the mutated
        // condition uses <= and will update RState when equal.
        assert(R_after == uint256(uint32(1)) ? false : true);
    }

    // Accept ETH (not used but allowed)
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 baseDeposit, uint256 quoteDeposit, address to) public payable {
        require(baseDeposit > 0, "need base input");
        // Precondition: ensure contract starts in BELOW_ONE state and deposits will cause BASE_RESERVE == BASE_TARGET after buy
        // We cannot directly set internal state; instead require current public observed R equals BELOW_ONE
        (, , , , , , uint256 Rbefore) = c.getPMMStateForCall();
        require(Rbefore == uint256(PMMPricing.RState.BELOW_ONE), "start not BELOW_ONE");

        // Transfer tokens into the vault by calling buyShares: we simulate by calling buyShares after external transfers
        // The test cannot actually transfer ERC20s; assume tokens are already set up so buyShares succeeds with provided deposits.
        // Call buyShares which in the counterexample leads to different BASE_TARGET when BASE_RESERVE equals BASE_TARGET
        c.buyShares(to);

        // Observe vault reserve and PMM state after
        (uint256 baseReserve, uint256 quoteReserve) = c.getVaultReserve();
        (, , , , uint256 B0, , uint256 Rafter) = c.getPMMStateForCall();

        // If BASE_RESERVE equals BASE_TARGET then original should keep R == BELOW_ONE; assert that holds
        assert(!(baseReserve == B0) || Rafter == uint256(PMMPricing.RState.BELOW_ONE));
    }
    receive() external payable { }
}

